const leader = 'db-leader';
const followers = ['db-f1', 'db-f2', 'db-f3'];

function chooseDb(userId, isWrite, lastWriteAt = 0) {
  if (isWrite) return leader;
  if (Date.now() - lastWriteAt < 5000) return leader;   // read-your-writes
  return followers[userId % followers.length];          // sticky = monotonic reads
}
```
Caveat: if that follower dies or lags badly, fall back to another one or the leader.
